<script setup>
import {ref,onMounted,onBeforeUnmount,computed} from 'vue';import ScreenCanvas from './ScreenCanvas.vue';import {fitScale} from '../layout.js';const props=defineProps({project:Object,playing:{default:true},assets:Object,publicSlug:String,mode:String});const host=ref(),size=ref({w:1920,h:1080});let observer;const scale=computed(()=>fitScale(props.project.width,props.project.height,size.value.w,size.value.h,props.mode||props.project.fit));onMounted(()=>{observer=new ResizeObserver(([entry])=>size.value={w:entry.contentRect.width,h:entry.contentRect.height});observer.observe(host.value);});onBeforeUnmount(()=>observer?.disconnect());
</script>
<template><div ref="host" class="aw-player-host"><div class="aw-player-scaled" :style="{width:project.width*scale.x+'px',height:project.height*scale.y+'px'}"><ScreenCanvas :project="project" :playing="playing" :assets="assets" :public-slug="publicSlug" :interactive="true" :style="{transform:`scale(${scale.x},${scale.y})`}"/></div></div></template>
